Practical usage notes: Overload for specific types (e.g., pointers or strings) to provide specialized behavior, ensure the function is marked as constexpr where possible for compile-time evaluation, and pass arguments by const reference to avoid overhead. In a function like print, call debug_rep on each argument to standardize output, as in: std::cout << debug_rep(arg) << std::endl;

code_example:
#include <iostream>
#include <string>
#include <vector>

template <typename T>
std::string debug_rep(const T& obj) {
    if constexpr (std::is_same_v<T, int>) {
        return std::to_string(obj);  // Handle int specifically
    } else if constexpr (std::is_same_v<T, std::string>) {
        return obj;  // Strings are already strings
    } else if constexpr (std::is_same_v<T, const char*>) {
        return std::string(obj);  // Convert C-string to std::string
    } else {
        return "[Unknown type]";  // Fallback for other types
    }
}

void print(const std::string& msg) {
    std::cout << debug_rep(msg) << std::endl;  // Call debug_rep on the argument
}

int main() {
    int num = 42;
    std::string text = "Hello, World!";
    print(debug_rep(num));  // Example: Pass debug_rep of an int
    print(text);            // Example: Pass a string directly
    return 0;
}
